var view = false;
			if (viewName == "month")
				view = "month";
			else if (viewName == "week")
				view = "agendaWeek";
			else if (viewName == "day")
				view = "agendaDay";

			if (view)
				jQuery("div#"+this.domCont.id).fullCalendar('changeView',view);

var _y = parseInt(year);
var _m = parseInt(month);
var _d = parseInt(day);
if (!isNaN(_y) && !isNaN(_m) && !isNaN(_d))
	jQuery("div#"+this.domCont.id).fullCalendar('gotoDate', _y , _m-1, _d);
